import { Currency } from "./money"
import type { Order } from "./order"

export interface Refund {
    orderId: string
    amount: number
    currency: Currency
}

const refunds: Refund[] = []

export function issueRefund(orderId: string, amount: number, currency: Currency = "EUR"): Refund {
    const refund = { orderId, amount, currency }
    refunds.push(refund)
    return refund
}

export function refundsOf(orderId: string): Refund[] {
    return refunds.filter((r) => r.orderId === orderId)
}

/*  full refund of a paid order  */
export function refundOrder(order: Order): Refund {
    if (order.status !== "paid")
        throw new Error("only paid orders can be refunded")
    return issueRefund(order.id, order.subtotal, order.currency)
}
import type { Order } from "./order"

const orders = new Map<string, Order>()

export async function saveOrder(order: Order): Promise<void> {
    if (orders.has(order.id))
        throw new Error(`order ${order.id} already exists`)
    orders.set(order.id, order)
}

export async function loadOrder(id: string): Promise<Order | undefined> {
    return orders.get(id)
}

export async function ordersOf(customerId: string): Promise<Order[]> {
    return [...orders.values()].filter((o) => o.customer.id === customerId)
}
const stock    = new Map<string, number>()
const reserved = new Map<string, number>()

export function setStock(sku: string, quantity: number): void {
    stock.set(sku, quantity)
}

export function available(sku: string): number {
    return (stock.get(sku) ?? 0) - (reserved.get(sku) ?? 0)
}

export function reserve(sku: string, quantity: number): boolean {
    if (available(sku) < quantity)
        return false
    reserved.set(sku, (reserved.get(sku) ?? 0) + quantity)
    return true
}

export function release(sku: string, quantity: number): void {
    const current = reserved.get(sku) ?? 0
    reserved.set(sku, Math.max(0, current - quantity))
